package cn.mop.persistence;

import cn.mop.domain.*;
import cn.mop.domain.contact.*;
import cn.mop.domain.contact.CustomerContactRepository.Access;
import cn.mop.domain.contact.ContactImportRepository.*;
import cn.mop.domain.contact.ContactImportJobState.*;
import javax.sql.DataSource;
import java.sql.*;
import java.time.*;
import java.util.*;

/** Dedicated durable job table only; never claims photo/import-source/other outboxes or changes identities. */
public final class PostgresContactImportRepository implements ContactImportRepository {
    private static final System.Logger LOG=System.getLogger(PostgresContactImportRepository.class.getName());
    private final DataSource source;private final PostgresPlatformRepository platform;private final PostgresCustomerContactRepository contacts;
    public PostgresContactImportRepository(DataSource source,PostgresPlatformRepository platform){this.source=Objects.requireNonNull(source);this.platform=Objects.requireNonNull(platform);contacts=new PostgresCustomerContactRepository(source,platform);}
    private record Stored(Job job,byte[] payload,String trace){}
    @Override public void authorizeAcceptance(Access access){contacts.authorizeWrite(access,null);}
    @Override public Job accept(Access a,List<CustomerContact> explicitRows){Connection c=platform.idempotentCommandConnection();authorizeAcceptance(a);List<CustomerContact> rows;
        try{rows=List.copyOf(explicitRows);}catch(RuntimeException failure){throw ContactImportPayloadCodec.invalid();}byte[] bytes=ContactImportPayloadCodec.encode(rows);String id=UUID.randomUUID().toString();
        if(a.traceId()==null||!a.traceId().matches("[A-Za-z0-9._:-]{1,128}"))throw ContactImportPayloadCodec.invalid();
        try{try(var s=statement(c,"INSERT INTO public.mop_contact_import_job(id,tenant_id,created_by,permission_version,row_count,payload_bytes,trace_id) VALUES (?::uuid,?::uuid,?::uuid,?,?,?,?)")){s.setString(1,id);s.setString(2,a.tenantId());s.setString(3,a.actorId());s.setLong(4,a.permissionVersion());s.setInt(5,rows.size());s.setBytes(6,bytes);s.setString(7,a.traceId());if(s.executeUpdate()!=1)throw corrupt();}audit(a,id,"accept","SUCCEEDED","QUEUED_CREATE_ONLY_NOT_IMPORTED");return read(c,id,a.tenantId(),a.actorId(),false).job();}catch(SQLException failure){throw unavailable(failure);}}
    @FunctionalInterface private interface ReadWork<T>{T run(Connection c)throws SQLException;}
    private <T>T readSnapshot(Access a,ReadWork<T> work){try(Connection c=source.getConnection()){c.setReadOnly(true);c.setTransactionIsolation(Connection.TRANSACTION_REPEATABLE_READ);c.setAutoCommit(false);try{authorizeRead(c,a);T value=work.run(c);c.commit();return value;}catch(SQLException|RuntimeException|Error failure){try{c.rollback();}catch(SQLException ignored){}throw failure;}}catch(SQLException failure){throw unavailable(failure);}}
    @Override public Job get(Access a,String id){String record=uuid(id);return readSnapshot(a,c->read(c,record,a.tenantId(),a.actorId(),false).job());}
    @Override public List<Job> list(Access a,int limit,Instant beforeCreatedAt,String beforeId){if(limit<1||limit>101||(beforeCreatedAt==null)!=(beforeId==null))throw ContactImportPayloadCodec.invalid();String cursor=beforeId==null?null:uuid(beforeId);if(beforeCreatedAt!=null&&(beforeCreatedAt.getNano()%1000000!=0||beforeCreatedAt.isBefore(Instant.parse("0001-01-01T00:00:00Z"))||beforeCreatedAt.isAfter(Instant.parse("9999-12-31T23:59:59.999Z"))))throw ContactImportPayloadCodec.invalid();return readSnapshot(a,c->{List<String> ids=new ArrayList<>();try(var s=statement(c,"SELECT id::text FROM public.mop_contact_import_job WHERE tenant_id=?::uuid AND created_by=?::uuid"+(beforeCreatedAt==null?"":" AND (created_at,id)<(?::timestamptz,?::uuid)")+" ORDER BY created_at DESC,id DESC LIMIT ?")){int at=1;s.setString(at++,a.tenantId());s.setString(at++,a.actorId());if(beforeCreatedAt!=null){instant(s,at++,beforeCreatedAt);s.setString(at++,cursor);}s.setInt(at,limit);try(var r=s.executeQuery()){while(r.next())ids.add(r.getString(1));}}List<Job> jobs=new ArrayList<>();for(String id:ids)jobs.add(read(c,id,a.tenantId(),a.actorId(),false).job());return List.copyOf(jobs);});}
    @Override public Optional<Claim> claimNext(String worker,Duration duration){return claimMatching(null,worker,duration);}
    @Override public Optional<Claim> claim(String jobId,String worker,Duration duration){return claimMatching(uuid(jobId),worker,duration);}
    private Optional<Claim> claimMatching(String target,String worker,Duration duration){
        // Validate worker and technical duration even when no queued row exists.
        ContactImportJobState.queued(1,Instant.EPOCH).claim(worker,Instant.EPOCH,duration);
        return platform.importJobTransaction(()->{Connection c=platform.importCommandConnection();try{Instant now=clock(c);String id=null;try(var s=statement(c,"SELECT id::text FROM public.mop_contact_import_job WHERE ((state='PENDING' AND next_at<=?::timestamptz) OR (state='LEASED' AND lease_until<=?::timestamptz))"+(target==null?"":" AND id=?::uuid")+" ORDER BY COALESCE(next_at,lease_until),created_at,id LIMIT 1 FOR UPDATE SKIP LOCKED")){s.setObject(1,OffsetDateTime.ofInstant(now,ZoneOffset.UTC));s.setObject(2,OffsetDateTime.ofInstant(now,ZoneOffset.UTC));if(target!=null)s.setString(3,target);try(var r=s.executeQuery()){if(r.next())id=r.getString(1);}}if(id==null)return Optional.empty();Stored current=read(c,id,null,null,false);var claimed=current.job().state().claim(worker,now,duration);if(claimed.isEmpty())return Optional.empty();transition(c,current.job(),claimed.get(),now);audit(access(current),id,"claim","SUCCEEDED","FENCED_LEASE_CLAIMED_NOT_IMPORTED");return Optional.of(new Claim(id,worker,claimed.get().fencingToken()));}catch(SQLException failure){throw unavailable(failure);}});
    }
    @Override public boolean process(Claim claim){validateClaim(claim);
        try{return platform.importJobTransaction(()->{Connection c=platform.importCommandConnection();try{Stored stored=read(c,claim.jobId(),null,null,true);if(!owned(stored,claim,clock(c)))return false;Job job=stored.job();Access a=access(stored);
            platform.idempotentAuthorized(a.actorId(),a.tenantId(),"WORKER /contact-imports/"+job.id(),"apply-v1",job.inputSha256(),a.permissionVersion(),()->contacts.authorizeWrite(a,null),()->{
                List<CustomerContact> rows=ContactImportPayloadCodec.decode(stored.payload(),job.state().rowCount(),job.inputSha256());var created=contacts.createBatch(a,rows);if(created.size()!=rows.size())throw corrupt();
                try{for(int i=0;i<created.size();i++){var row=created.get(i);if(!row.facts().equals(rows.get(i))||!row.createdBy().equals(a.actorId())||!row.tenantId().equals(a.tenantId())||row.version()!=1)throw corrupt();try(var s=statement(c,"INSERT INTO public.mop_contact_import_result(tenant_id,job_id,row_number,row_count,contact_id,contact_version) VALUES (?::uuid,?::uuid,?,?,?::uuid,1)")){s.setString(1,a.tenantId());s.setString(2,job.id());s.setInt(3,i+1);s.setInt(4,rows.size());s.setString(5,row.id());if(s.executeUpdate()!=1)throw corrupt();}}
                    Instant now=clock(c);var success=job.state().succeed(claim.worker(),claim.fencingToken(),now,created.size());transition(c,job,success,now);audit(a,job.id(),"complete","SUCCEEDED","ALL_CONTACT_ROWS_CREATED_NO_NOTIFICATION");return Map.of("job_id",job.id(),"row_count",created.size(),"contact_ids",created.stream().map(CustomerContactRepository.Entry::id).toList());
                }catch(SQLException failure){throw unavailable(failure);}
            });
            Job current=read(c,job.id(),null,null,false).job();if(current.state().state()!=State.SUCCEEDED)throw corrupt();return true;
        }catch(SQLException failure){throw unavailable(failure);}});}catch(DomainException failure){
            if(failure.code.equals("STALE_IMPORT_LEASE")||failure.code.equals("OBJECT_NOT_FOUND"))return false;
            Failure terminal=failure.status==401||failure.status==403?Failure.AUTHORIZATION_REVOKED:failure.code.equals("INVALID_CONTACT_IMPORT_PAYLOAD")?Failure.PAYLOAD_INVALID:failure.code.equals("LAST_ENABLED_DECISION_MAKER")?Failure.LAST_ENABLED_DECISION_MAKER:null;
            if(terminal!=null)return settle(claim,terminal);
            if(failure.status==503){settle(claim,null);return false;}
            throw failure;
        }
    }
    private boolean settle(Claim claim,Failure terminal){return platform.importJobTransaction(()->{Connection c=platform.importCommandConnection();try{Stored stored=read(c,claim.jobId(),null,null,true);Instant now=clock(c);if(!owned(stored,claim,now))return false;var next=terminal==null?stored.job().state().retry(claim.worker(),claim.fencingToken(),now,now.plusSeconds(5)):stored.job().state().fail(claim.worker(),claim.fencingToken(),now,terminal);transition(c,stored.job(),next,now);audit(access(stored),claim.jobId(),terminal==null?"retry":"fail",terminal==null?"PENDING":"FAILED",terminal==null?"UPSTREAM_UNAVAILABLE":terminal.name());return terminal!=null;}catch(SQLException failure){throw unavailable(failure);}});}
    private static boolean owned(Stored stored,Claim claim,Instant now){var state=stored.job().state();return state.state()==State.LEASED&&claim.worker().equals(state.leaseOwner())&&claim.fencingToken()==state.fencingToken()&&!now.isBefore(state.leaseStartedAt())&&now.isBefore(state.leaseUntil());}
    private static void transition(Connection c,Job before,ContactImportJobState next,Instant now)throws SQLException{if(before.version()>=ContactImportJobState.MAX_COUNTER)throw corrupt();try(var s=statement(c,"UPDATE public.mop_contact_import_job SET state=?,attempts=?,fencing_token=?,lease_owner=?,lease_started_at=?,lease_until=?,next_at=?,completed_rows=?,error_code=?,version=version+1,updated_at=? WHERE id=?::uuid AND version=?")){s.setString(1,next.state().name());s.setLong(2,next.attempts());s.setLong(3,next.fencingToken());s.setString(4,next.leaseOwner());instant(s,5,next.leaseStartedAt());instant(s,6,next.leaseUntil());instant(s,7,next.nextAt());if(next.completedRows()==null)s.setNull(8,Types.INTEGER);else s.setInt(8,next.completedRows());s.setString(9,next.error()==null?null:next.error().name());instant(s,10,now);s.setString(11,before.id());s.setLong(12,before.version());if(s.executeUpdate()!=1)throw new DomainException(409,"STALE_IMPORT_LEASE","导入状态已被另一执行者更新");}}
    private static Stored read(Connection c,String id,String tenant,String actor,boolean lock)throws SQLException{
        String sql="SELECT * FROM public.mop_contact_import_job WHERE id=?::uuid"+(tenant==null?"":" AND tenant_id=?::uuid AND created_by=?::uuid")+(lock?" FOR UPDATE":"");
        try(var s=statement(c,sql)){s.setString(1,id);if(tenant!=null){s.setString(2,tenant);s.setString(3,actor);}try(var r=s.executeQuery()){if(!r.next())throw missing();try{
            if(!"contact-create-only-v1".equals(r.getString("source_format")))throw corrupt();String record=uuid(r.getString("id")),scope=uuid(r.getString("tenant_id")),owner=uuid(r.getString("created_by"));long permission=r.getLong("permission_version"),version=r.getLong("version");if(permission<1||permission>ContactImportJobState.MAX_COUNTER||version<1||version>ContactImportJobState.MAX_COUNTER)throw corrupt();
            String error=r.getString("error_code");var state=new ContactImportJobState(State.valueOf(r.getString("state")),r.getInt("row_count"),r.getLong("attempts"),r.getLong("fencing_token"),r.getString("lease_owner"),time(r,"lease_started_at"),time(r,"lease_until"),time(r,"next_at"),(Integer)r.getObject("completed_rows"),error==null?null:Failure.valueOf(error));
            Instant created=time(r,"created_at"),updated=time(r,"updated_at");if(created==null||updated==null||updated.isBefore(created))throw corrupt();String hash=r.getString("input_sha256");byte[] payload=r.getBytes("payload_bytes");if(hash==null||!hash.matches("[0-9a-f]{64}")||payload==null||!ContactImportPayloadCodec.hash(payload).equals(hash))throw corrupt();List<ResultLink> results=results(c,record,scope,owner);if(state.state()==State.SUCCEEDED?results.size()!=state.rowCount():!results.isEmpty())throw corrupt();return new Stored(new Job(record,scope,owner,permission,hash,state,version,created,updated,results),payload,r.getString("trace_id"));
        }catch(DomainException failure){throw failure;}catch(RuntimeException failure){throw corrupt();}}}
    }
    private static List<ResultLink> results(Connection c,String id,String tenant,String actor)throws SQLException{List<ResultLink> result=new ArrayList<>();try(var s=statement(c,"SELECT r.row_number,r.contact_id::text,r.contact_version,h.created_by::text FROM public.mop_contact_import_result r JOIN public.mop_customer_contact h ON h.tenant_id=r.tenant_id AND h.id=r.contact_id WHERE r.tenant_id=?::uuid AND r.job_id=?::uuid ORDER BY r.row_number LIMIT 101")){s.setString(1,tenant);s.setString(2,id);try(var r=s.executeQuery()){while(r.next()){if(r.getInt(1)!=result.size()+1||r.getLong(3)!=1||!actor.equals(r.getString(4))||result.size()>=100)throw corrupt();result.add(new ResultLink(r.getInt(1),uuid(r.getString(2)),r.getLong(3)));}}}return List.copyOf(result);}
    private static Access access(Stored stored){var j=stored.job();return new Access(j.createdBy(),j.tenantId(),j.permissionVersion(),stored.trace());}
    private void audit(Access a,String id,String action,String result,String reason){platform.audit(a.actorId(),a.tenantId(),"customer_contact_import."+action,"customer_contact_import",id,result,reason,a.traceId());}
    private static void authorizeRead(Connection c,Access a)throws SQLException{if(a==null)throw expired();PostgresAuthorization.require(c,a.actorId(),a.tenantId(),a.permissionVersion(),"contacts:write");if(a==null||a.permissionVersion()<1)throw expired();uuid(a.actorId());uuid(a.tenantId());try(var s=statement(c,"SELECT m.role_code,m.permission_version FROM public.mop_membership m JOIN public.mop_user u ON u.id=m.user_id WHERE m.tenant_id=?::uuid AND m.user_id=?::uuid AND m.active AND u.active")){s.setString(1,a.tenantId());s.setString(2,a.actorId());try(var r=s.executeQuery()){if(!r.next()||r.getLong(2)!=a.permissionVersion())throw expired();if(!Set.of("padmin","tadmin").contains(r.getString(1)))throw new DomainException(403,"ACTION_FORBIDDEN","仅当前授权管理员可读取自己的联系人导入作业");}}}
    private static Instant clock(Connection c)throws SQLException{try(var s=statement(c,"SELECT clock_timestamp()::timestamptz(3)");var r=s.executeQuery()){if(!r.next())throw corrupt();return r.getObject(1,OffsetDateTime.class).toInstant();}}
    private static Instant time(ResultSet r,String column)throws SQLException{var value=r.getObject(column,OffsetDateTime.class);return value==null?null:value.toInstant();}
    private static void instant(PreparedStatement s,int at,Instant value)throws SQLException{if(value==null)s.setNull(at,Types.TIMESTAMP_WITH_TIMEZONE);else s.setObject(at,OffsetDateTime.ofInstant(value,ZoneOffset.UTC));}
    private static PreparedStatement statement(Connection c,String sql)throws SQLException{var s=c.prepareStatement(sql);s.setQueryTimeout(10);return s;}
    private static String uuid(String value){if(value==null||!value.matches("[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}"))throw new DomainException(400,"VALIDATION_ERROR","导入作业标识无效");return UUID.fromString(value).toString();}
    private static void validateClaim(Claim claim){if(claim==null||claim.worker()==null||!claim.worker().matches("[A-Za-z0-9._:-]{1,64}")||claim.fencingToken()<1||claim.fencingToken()>ContactImportJobState.MAX_COUNTER)throw new DomainException(400,"VALIDATION_ERROR","领取标识无效");uuid(claim.jobId());}
    private static DomainException expired(){return new DomainException(401,"SESSION_EXPIRED","当前成员关系或权限版本失效");}
    private static DomainException missing(){return new DomainException(404,"OBJECT_NOT_FOUND","对象不存在或不可见");}
    private static DomainException corrupt(){return new DomainException(503,"UPSTREAM_UNAVAILABLE","联系人导入记录不一致，未返回成功结果");}
    private static DomainException unavailable(SQLException failure){String state=failure.getSQLState();LOG.log(System.Logger.Level.WARNING,"Contact import PostgreSQL failure sql_state={0}",state!=null&&state.matches("[A-Z0-9]{5}")?state:"UNKNOWN");return new DomainException(503,"UPSTREAM_UNAVAILABLE","联系人导入数据库不可用，未确认执行结果");}
    @Override public List<String> readinessProblems(){try(Connection c=source.getConnection()){c.setReadOnly(true);TestSchemaMigration.verifyContactImports(c);return List.of();}catch(SQLException|RuntimeException failure){return List.of("CONTACT_IMPORT_SCHEMA_OR_GENERATED_GUARD_NOT_READY");}}
}
